function isLegalOpen(panel, outer){
  const head=panel && panel.querySelector('.v85-routine-modal-head');
  const title=head && head.querySelector('h2');
  return !!(outer && panel && outer.classList.contains('open') && title && /dominio\s+jur[ií]dico/i.test(title.textContent||''));
}
function applyFix(){
  ensureStyle();
  const outer=document.getElementById('windowContainer');
  const panel=document.getElementById('windowContent');
  if(!outer || !panel)return;
  if(!isLegalOpen(panel,outer)){
    outer.classList.remove('tf22-legal-fix-open');
    panel.classList.remove('tf22-legal-fix');
    return;
  }
  outer.classList.add('tf22-legal-fix-open');
  panel.classList.add('tf22-legal-fix');
  outer.style.overflowY='auto';
  outer.style.overflowX='hidden';
  outer.style.webkitOverflowScrolling='touch';
  outer.style.touchAction='pan-y';
  panel.style.overflow='visible';
  panel.style.height='auto';
  const progress=panel.querySelector(':scope > .tf21-progress');
  const rule=panel.querySelector(':scope > .tf21-rule');
  const list=panel.querySelector('.v83-legal-list.v97-routine-scroll');
  if(progress){
    progress.style.height='auto';
    progress.style.maxHeight='none';
    progress.style.overflow='visible';
  }
  if(rule){
    rule.style.position='relative';
  }
  if(list){
    list.style.overflow='visible';
    list.style.height='auto';
    list.style.maxHeight='none';
    list.style.touchAction='pan-y';
    list.querySelectorAll(':scope > .v97-routine-guide-wrap').forEach((wrap)=>{
      wrap.style.transform='none';
      wrap.style.margin='0';
      wrap.style.position='relative';
    });
  }
