function ensureStyle(){
 let st=document.getElementById('tfT28LegalReferenceStyle');
 if(!st){st=document.createElement('style');st.id='tfT28LegalReferenceStyle';st.textContent=STYLE;document.head.appendChild(st);}
 else if(st.textContent!==STYLE)st.textContent=STYLE;
}
function legalOpen(){
 const outer=document.getElementById('windowContainer'),panel=document.getElementById('windowContent');
 const title=panel&&panel.querySelector('.v85-routine-modal-head h2');
 return {outer,panel,ok:!!(outer&&panel&&outer.classList.contains('open')&&title&&/dominio\s+jur[ií]dico/i.test(title.textContent||''))};
}
function setText(el,value){if(el&&el.textContent.trim()!==value)el.textContent=value;}
function apply(){
 ensureStyle();
 const {outer,panel,ok}=legalOpen();if(!outer||!panel)return;
 if(!ok){outer.classList.remove('tf28-legal-open');panel.classList.remove('tf28-legal-reference');return;}
 outer.classList.add('tf28-legal-open');panel.classList.add('tf28-legal-reference');
 const head=panel.querySelector('.v85-routine-modal-head');
 const eyebrow=head&&head.querySelector('.v85-routine-modal-copy .eyebrow,.v85-routine-modal-copy .v85-routine-kicker,.v85-routine-modal-copy .tf21-kicker');
 setText(eyebrow,'ENTRENAMIENTO JURÍDICO');
 const title=head&&head.querySelector('h2');
 setText(title,'Dominio jurídico');
 if(title&&!title.querySelector('.tf31-title-cyan')){
   const cyan=document.createElement('span');cyan.className='tf31-title-cyan';cyan.textContent='Dominio ';
   const violet=document.createElement('span');violet.className='tf31-title-violet';violet.textContent='jurídico';
   title.replaceChildren(cyan,violet);
 }
 setText(head&&head.querySelector('.tf21-subtitle'),'Norma · Caso · Argumento · Defensa · Escritura');
 const list=panel.querySelector('.v83-legal-list.v97-routine-scroll,.v97-routine-scroll');
 if(list&&!list.classList.contains('v83-legal-list'))list.classList.add('v83-legal-list');
 const rule=panel.querySelector('.tf21-rule');
 if(list&&rule&&(rule.parentElement!==list||list.firstElementChild!==rule))list.insertBefore(rule,list.firstChild);
 const expected=[
  ['Domina una norma','Explica regla, efecto y límite.'],
  ['Resuelve un caso','Hechos, regla, análisis y conclusión.'],
  ['Ataca tu argumento','Formula la objeción más fuerte y respóndela.'],
  ['Defiende sin leer','Expón 3 minutos sin notas.'],
  ['Escribe como jurista','Una idea, fundamento y cero relleno.']
 ];
 const rows=list?[...list.querySelectorAll(':scope > .v97-routine-guide-wrap.tf21-mission')]:[];
 rows.forEach((wrap,i)=>{
   wrap.classList.add('tf31-mission-'+(i+1));
   wrap.classList.toggle('tf28-cyan',i%2===0);wrap.classList.toggle('tf28-violet',i%2===1);
   const num=wrap.querySelector('.tf21-num');setText(num,String(i+1).padStart(2,'0'));
   const strong=wrap.querySelector('.v83-legal-step-copy strong');const desc=wrap.querySelector('.v83-legal-step-copy span');
   if(expected[i]){setText(strong,expected[i][0]);setText(desc,expected[i][1]);}
   const summary=wrap.querySelector('summary');if(summary){
     // Cambiar solo el nodo de texto principal y conservar cualquier contenido interactivo existente.
     const textNodes=[...summary.childNodes].filter(n=>n.nodeType===Node.TEXT_NODE);
     if(textNodes.length){if(textNodes[0].nodeValue!=='Cómo completarla · paso a paso')textNodes[0].nodeValue='Cómo completarla · paso a paso';for(let j=1;j<textNodes.length;j++)if(textNodes[j].nodeValue)textNodes[j].nodeValue='';}
     else summary.insertBefore(document.createTextNode('Cómo completarla · paso a paso'),summary.firstChild);
   }
 });
}
let queued=false;function schedule(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;apply();});}
